# Code generated by Claude
"""
The held beaker's contacts through the pipeline episode (David 2026-10-25): the plan "navigate to the beaker, pick it up, navigate to the hotplate, place it" runs with the run kept (recording, episode log)
and a test source that logs, per orchestrator segment and phase, every contact of the beaker's geoms (pair, first and last time, ticks, largest normal force) and the smallest distances of the beaker's
geoms to the hotplate's geoms and to the fingers' geoms. Nothing in the algorithm or the full check changes.

    MUJOCO_GL=egl python experiments/held_beaker_contacts.py [--at-reference-stance] --out data/held_beaker/<name>

Writes <out>/contacts.json (also printed in short) and the kept episode (<out>/episode, <out>/recording).
"""

import argparse
import gc
import json
import os
import shutil
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src.episode_runner import run_episode  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import BENCH_STANCE_CFG, TASK_CFG  # noqa: E402
from stance_select_test import PLAN4  # noqa: E402


def descendants(model, root):
    ids = {model.body(root).id}
    for b in range(model.nbody):
        p = b
        while p:
            if p in ids:
                ids.add(b)
                break
            p = int(model.body_parentid[p])
    return ids


def make_source(model, data, task, dist_every=2):
    """The test source: contacts of the beaker's geoms and the distances to the hotplate and the fingers."""
    beaker = descendants(model, "task_beaker")
    plate = descendants(model, "task_hotplate")
    bg = [g for g in range(model.ngeom) if int(model.geom_bodyid[g]) in beaker]
    hg = [g for g in range(model.ngeom) if int(model.geom_bodyid[g]) in plate and (model.geom_contype[g] or model.geom_conaffinity[g])]
    fg = [g for g in range(model.ngeom) if "finger" in model.body(int(model.geom_bodyid[g])).name and (model.geom_contype[g] or model.geom_conaffinity[g])]
    bset = set(bg)
    gname = lambda g: model.geom(g).name or f"geom{g}"
    bname = lambda g: model.body(int(model.geom_bodyid[g])).name
    S = {"contacts": {}, "dist": {}, "n": 0, "geoms": {"beaker": len(bg), "hotplate": len(hg), "fingers": len(fg)}}
    f6 = np.zeros(6)
    ft = np.zeros(6)

    def step(obs):
        S["n"] += 1
        ep = obs.get("policy")
        orch = task["pipeline"].get("orchestrator")
        if not ep or not orch:
            return None
        seg = sum(1 for x in orch["state"]["status"] if x == "done")          # 0 based index of the current plan segment
        key = f"seg{seg}|{ep['phase']}"
        t = float(data.time)
        for i in range(data.ncon):
            c = data.contact[i]
            a, b = int(c.geom1), int(c.geom2)
            if (a in bset) == (b in bset):
                continue
            mine, other = (a, b) if a in bset else (b, a)
            mujoco.mj_contactForce(model, data, i, f6)
            r = S["contacts"].setdefault(key, {}).setdefault(f"{gname(mine)} / {bname(other)}:{gname(other)}", {"first_s": t, "last_s": t, "ticks": 0, "max_force_N": 0.0, "min_dist_m": 1e9})
            r["last_s"] = t
            r["ticks"] += 1
            r["max_force_N"] = max(r["max_force_N"], float(f6[0]))
            r["min_dist_m"] = min(r["min_dist_m"], float(c.dist))
        if S["n"] % dist_every == 0:
            rec = S["dist"].setdefault(key, {})
            for name, targets in (("hotplate", hg), ("fingers", fg)):
                for a in bg:
                    for b in targets:
                        d = mujoco.mj_geomDistance(model, data, a, b, 0.3, ft)
                        if name not in rec or d < rec[name]["m"]:
                            rec[name] = {"m": float(d), "t_s": t, "beaker_geom": gname(a), "other": f"{bname(b)}:{gname(b)}"}
        return None

    return {"name": "held_beaker", "step": step, "state": S}


def main(args):
    out = Path(args.out)
    for sub in ("episode", "recording"):
        shutil.rmtree(out / sub, ignore_errors=True)
    out.mkdir(parents=True, exist_ok=True)
    if args.at_reference_stance:
        BENCH_STANCE_CFG["navigation"] = False       # navigation off: the robot stays at TASK_CFG's stance (the reference stance for tests), the selection only checks that it serves the plan
    task = make_pipeline_task(PLAN4)
    gc.collect()
    rep = task["stance_selection"]
    st = rep["runs"][0]["stance"] if rep else {"xy": list(TASK_CFG["staging_xy"]), "q": TASK_CFG["pedestal_q"], "yaw": TASK_CFG["staging_yaw"]}
    print(f"at the reference stance {args.at_reference_stance}: stance xy {np.round(st['xy'], 3).tolist()} pedestal {st['q']}", flush=True)
    sim = load_task(cameras=True)
    src = {}

    def extra(m, d):
        src["s"] = make_source(m, d, task)
        return {"held_beaker": src["s"]}

    s = run_episode(task, sim.model, sim.data, out_dir=out / "episode", record_dir=out / "recording", extra_sources=extra)
    state = task["pipeline"]["orchestrator"]["state"]
    ok, diag = task["check_success"](sim.model, sim.data)
    S = src["s"]["state"]
    res = {"at_reference_stance": args.at_reference_stance, "stance": st, "outcome": s["outcome"], "status": state["status"], "success": bool(ok), "geoms": S["geoms"], "contacts": S["contacts"], "distances": S["dist"],
           "sim_time_end": float(sim.data.time)}
    tmp = out / "contacts.json.tmp"
    tmp.write_text(json.dumps(res, indent=1, default=str))
    tmp.replace(out / "contacts.json")
    print(f"outcome {s['outcome']} status {state['status']} beaker on hotplate {ok}")
    for key in sorted(set(S["contacts"]) | set(S["dist"])):
        print(f"\n{key}")
        for k, v in S["contacts"].get(key, {}).items():
            print(f"  contact {k}: {v['first_s']:.2f}-{v['last_s']:.2f} s, {v['ticks']} ticks, max force {v['max_force_N']:.2f} N")
        for k, v in S["dist"].get(key, {}).items():
            print(f"  closest to {k}: {1000 * v['m']:.1f} mm at {v['t_s']:.2f} s ({v['beaker_geom']} / {v['other']})")
    return s["outcome"] == "SUCCESS"


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--at-reference-stance", action="store_true", help="stay at TASK_CFG's stance (the reference stance for tests) instead of the region's pick: navigation off for the run")
    ap.add_argument("--out", required=True)
    sys.exit(0 if main(ap.parse_args()) else 1)
